findings.fix:
variable "security_principal" {
  type        = string
  description = "Group or service account granted roles/iam.securityReviewer on the folder"

  validation {
    condition     = can(regex("^(group|serviceAccount):", var.security_principal))
    error_message = "var.security_principal must be a group or service account"
  }
}

validation {
  condition     = !can(regex("(compute@developer|appspot)[.]gserviceaccount[.]com$", var.security_group))
  error_message = "var.security_group must not be a default Compute or App Engine service account"
}

validation {
  condition     = !can(regex("@(gmail|googlemail)[.]com$", var.security_group))
  error_message = "var.security_group must not be a personal Gmail account"
}

validation {
  condition     = alltrue([for t in ["ADMIN_READ", "DATA_WRITE"] : contains(var.audit_log_types, t)])
  error_message = "var.audit_log_types must include ADMIN_READ and DATA_WRITE; only DATA_READ is optional"
}
